const months=['ENE','FEB','MAR','ABR','MAY','JUN','JUL','AGO','SEP','OCT','NOV','DIC'];
const departments={cusco:{name:'CUSCO',base:84},cajamarca:{name:'CAJAMARCA',base:71},huanuco:{name:'HUÁNUCO',base:63},ucayali:{name:'UCAYALI',base:97},'madre-de-dios':{name:'MADRE DE DIOS',base:88}};
const fromYear=document.querySelector('#fromYear');const toYear=document.querySelector('#toYear');
for(let y=2019;y<=2026;y++){fromYear.add(new Option(y,y));toYear.add(new Option(y,y))}fromYear.value='2021';toYear.value='2026';
function seeded(seed){let x=Math.sin(seed)*10000;return x-Math.floor(x)}
function render(){const key=document.querySelector('#department').value;const dep=departments[key];let start=+fromYear.value,end=+toYear.value;if(start>end){[start,end]=[end,start];fromYear.value=start;toYear.value=end}const heat=document.querySelector('#heatmap');heat.innerHTML='<div></div>'+months.map(m=>`<div class="month-label">${m}</div>`).join('');let total=0;for(let y=start;y<=end;y++){heat.insertAdjacentHTML('beforeend',`<div class="year-label">${y}</div>`);for(let m=0;m<12;m++){const seasonal=m>5&&m<10?1.8:.55;const value=Math.round((seeded(y*17+m*31+dep.base)*42+dep.base/3)*seasonal);total+=value;const level=Math.min(5,Math.floor(value/25));heat.insertAdjacentHTML('beforeend',`<div class="cell level-${level}" title="${months[m]} ${y}: ${value} eventos">${value}</div>`)}}document.querySelector('#areaName').textContent=dep.name;document.querySelector('#eventCount').textContent=total.toLocaleString('es-PE');const anomaly=Math.round((seeded(total)*38)-8);const anomalyEl=document.querySelector('#anomaly');anomalyEl.textContent=`${anomaly>=0?'+':''}${anomaly}%`;anomalyEl.className=anomaly>=0?'positive':''}
document.querySelector('#updateBtn').addEventListener('click',render);document.querySelector('#department').addEventListener('change',render);
document.querySelector('#downloadBtn').addEventListener('click',()=>{const dep=departments[document.querySelector('#department').value].name;const rows=['departamento,anio,mes,eventos,nota'];for(let y=+fromYear.value;y<=+toYear.value;y++)for(let m=0;m<12;m++){const n=Math.round(seeded(y*17+m*31)*120);rows.push(`${dep},${y},${m+1},${n},dato_sintetico_demo`)}const blob=new Blob([rows.join('\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`fuego-vivo-${dep.toLowerCase().replaceAll(' ','-')}.csv`;a.click();URL.revokeObjectURL(a.href)});render();
